# Implement the solution pattern from the .py file
from collections import Counter

def apply_transform(grid):
    # Find background color (most common value)
    c = Counter(x for r in grid for x in r)
    bg = c.most_common(1)[0][0]

    # Find all non-background points
    pts = []
    for i, row in enumerate(grid):
        for j, x in enumerate(row):
            if x != bg:
                pts.append((i, j))

    if not pts:
        return [row[:] for row in grid]

    # Get bounding box
    r0, r1 = min(p[0] for p in pts), max(p[0] for p in pts)
    c0, c1 = min(p[1] for p in pts), max(p[1] for p in pts)

    # Create output grid
    o = [row[:] for row in grid]

    # Fill bounding-box borders with 2s where background
    # Top and bottom borders
    for j in range(c0, c1 + 1):
        if o[r0][j] == bg:
            o[r0][j] = 2
        if o[r1][j] == bg:
            o[r1][j] = 2

    # Left and right borders
    for i in range(r0, r1 + 1):
        if o[i][c0] == bg:
            o[i][c0] = 2
        if o[i][c1] == bg:
            o[i][c1] = 2

    # Fill broken interior horizontal lines
